      const cen = { parsedScript: pr, scenes: VB.resolveVerbatimSegments(pr, clips).map(cenaDe), planScenes: B.splitScriptToScenes(roteiro).map((s, k) => ({ brollPrompt: `Aligned plan prompt ${k + 1}: ${s.narration}` })) }
